from espzero import esp_led, Servo, Buzzer
from time import sleep

door_servo = Servo(13)
buzzer = Buzzer(15)

print("🚪 [Smart Doorlock] Security system activated")

# 1. Auth success: Green LED + double beep + door open (90 deg)
print("Access granted: Lock released and door opened.")
esp_led.color = (0, 255, 0)
esp_led.on()
buzzer.beep(on_time=0.1, off_time=0.1, n=2)
door_servo.move_to_degree(90)
sleep(1.0)

# 2. Door close: Red LED + door closed (0 deg)
print("Door closed and locked.")
esp_led.color = (255, 0, 0)
esp_led.on()
door_servo.move_to_degree(0)
sleep(0.5)

esp_led.off()
print("Doorlock secured. Stay safe!")
